    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    M = int(input[idx])
    idx += 1

    edges = []
    adj = [[] for _ in range(N + 1)]
    for _ in range(M):
        a = int(input[idx])
        idx += 1
        b = int(input[idx])
        idx += 1
        c = int(input[idx])
        idx += 1
        edges.append((a, b, c))
        adj[a].append((b, c))
        adj[b].append((a, c))

    # Compute all-pairs shortest paths using Dijkstra's algorithm
    dist = [[float('inf')] * (N + 1) for _ in range(N + 1)]
    for s in range(1, N + 1):
        dist_s = dist[s]
        dist_s[s] = 0
        heap = [(0, s)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist_s[u]:
                continue
            for v, c in adj[u]:
                if dist_s[v] > d + c:
                    dist_s[v] = d + c
                    heapq.heappush(heap, (dist_s[v], v))

    # Check each edge to see if it's used in any shortest path
    count = 0
    for a, b, c in edges:
        used = False
        for s in range(1, N + 1):
            for t in range(1, N + 1):
                if s == t:
                    continue
                # Check if the edge a->b is on any shortest path from s to t
                if dist[s][a] + c + dist[b][t] == dist[s][t]:
                    used = True
                    break
                # Check if the edge b->a is on any shortest path from s to t
                if dist[s][b] + c + dist[a][t] == dist[s][t]:
                    used = True
                    break
            if used:
                break
        if not used:
            count += 1

    print(count)

