def main():
    N, M, *rest = list(map(int, sys.stdin.read().split()))
    allowed_digits = rest[:M]
    allowed_digits = list(set(allowed_digits))  # Remove duplicates
    allowed_digits = [str(d) for d in allowed_digits]
    allowed_digits = sorted(allowed_digits, reverse=True)

    matchsticks = {
        '0': 6,
        '1': 2,
        '2': 5,
        '3': 5,
        '4': 4,
        '5': 5,
        '6': 6,
        '7': 3,
        '8': 7,
        '9': 6
    }
    allowed_matchsticks = [matchsticks[d] for d in allowed_digits]
    min_s = min(allowed_matchsticks)
    k_max = N // min_s
    rem = N - k_max * min_s

    # Compute all possible increases
    increases = []
    for i in range(len(allowed_digits)):
        for j in range(len(allowed_digits)):
            if i == j:
                continue
            s_i = allowed_matchsticks[i]
            s_j = allowed_matchsticks[j]
            if s_j > s_i:
                increases.append(s_j - s_i)
    increases = list(set(increases))  # Remove duplicates
    increases.sort(reverse=True)

    # Dynamic programming to check if rem can be formed
    dp = [False] * (rem + 1)
    dp[0] = True
    for inc in increases:
        for j in range(rem, -1, -1):
            if dp[j]:
                if j + inc <= rem:
                    dp[j + inc] = True

    if not dp[rem]:
        print(-1)  # According to the problem statement, a solution exists
    else:
        result = []
        rem_match = N
        rem_digits = k_max
        for i in range(k_max):
            for d in allowed_digits:
                if i == 0 and d == '0':
                    continue
                s = matchsticks[d]
                if s > rem_match:
                    continue
                if rem_digits == 1:
                    if s == rem_match:
                        result.append(d)
                        rem_match -= s
                        rem_digits -= 1
                        break
                else:
                    # Check if the remaining can be formed
                    @lru_cache(maxsize=None)
                    def can_form(rem_m, rem_d):
                        if rem_d == 0:
                            return rem_m == 0
                        for digit in allowed_digits:
                            if digit == '0' and rem_d == 0:
                                continue
                            m = matchsticks[digit]
                            if m > rem_m:
                                continue
                            if rem_d == 1:
                                if m == rem_m:
                                    return True
                            else:
                                if can_form(rem_m - m, rem_d - 1):
                                    return True
                        return False
                    if can_form(rem_match - s, rem_digits - 1):
                        result.append(d)
                        rem_match -= s
                        rem_digits -= 1
                        break
        print(''.join(result))

