        edges.append((a, b))
        adj[a].append(b)
        rev_adj[b].append(a)

    # First pass to get the order
    visited = [False] * (n + 1)
    order = []
    for u in range(1, n + 1):
        if not visited[u]:
            stack = [(u, False)]
            while stack:
                node, processed = stack.pop()
                if processed:
                    order.append(node)
                    continue
                if visited[node]:
                    continue
                visited[node] = True
                stack.append((node, True))
                for v in adj[node]:
                    if not visited[v]:
                        stack.append((v, False))

    # Second pass on reversed graph
    visited = [False] * (n + 1)
    components = []
    for u in reversed(order):
        if not visited[u]:
            component = []
            stack = [u]
            visited[u] = True
            component.append(u)
            while stack:
                node = stack.pop()
                for v in rev_adj[node]:
                    if not visited[v]:
                        visited[v] = True
                        component.append(v)
                        stack.append(v)
            components.append(component)

    # Assign component id to each vertex
    vertex_component = [0] * (n + 1)
    for i, comp in enumerate(components):
        for u in comp:
            vertex_component[u] = i

    # Count edges within each component
    edge_counts = [0] * len(components)
    for a, b in edges:
        if vertex_component[a] == vertex_component[b]:
            edge_counts[vertex_component[a]] += 1

    # Find the component that is a cycle
    selected_component = None
    selected_component_id = -1
    for i in range(len(components)):
        if edge_counts[i] == len(components[i]):
            selected_component = components[i]
