def compute_xor(n):
    if n < 0:
        return 0
    result = 0
    i = 0
    while (1 << i) <= n:
        divisor = 1 << (i + 1)
        full_cycles = (n + 1) // divisor
        remainder = (n + 1) % divisor
        if remainder > (1 << i):
            result |= (1 << i)
        i += 1
    return result

