def count_valid_ks(N):
    count = 0
    if N >= 2:
        count += 1  # K = N
    if (N - 1) >= 2:
        count += 1  # K = N-1

    # Find all proper divisors of N (>=2 and < N)
    proper_divisors = set()
    for i in range(2, int(math.isqrt(N)) + 1):
        if N % i == 0:
            if i < N:
                proper_divisors.add(i)
            j = N // i
            if j != i and j < N:
                proper_divisors.add(j)
    # Check if N is a perfect square
    sqrt_n = math.isqrt(N)
    if sqrt_n * sqrt_n == N and sqrt_n < N:
        proper_divisors.add(sqrt_n)

    for K in proper_divisors:
        m = N // K
        while m >= K:
            if m % K == 0:
                m = m // K
            else:
                m -= K
        if m == 1:
            count += 1
    return count

