    # Check all divisors K of n where n/K is prime and K <= n/K
    def is_prime(x):
        if x < 2:
            return False
        for i in range(2, int(x**0.5)+1):
            if x % i == 0:
                return False
        return True

    for k in range(2, int(n**0.5) + 1):
        if n % k == 0:
            quotient = n // k
            if is_prime(quotient) and k <= quotient:
                count += 1

    # Check all K where n - K is prime and K <= n - K
    # Which is equivalent to K <= (n - K) => 2K <= n => K <= n//2
    for k in range(2, (n // 2) + 1):
        if (n - k) == 1:
            count += 1
        else:
            if is_prime(n - k) and k <= (n - k):
                count += 1

    return count

