        return []
    factors = {}
    while n % 2 == 0:
        factors[2] = factors.get(2, 0) + 1
        n = n // 2
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors[i] = factors.get(i, 0) + 1
            n = n // i
        i += 2
    if n > 1:
        factors[n] = 1
    divisors = [1]
    for p in factors:
        exponents = [p**e for e in range(1, factors[p]+1)]
        current_length = len(divisors)
        for exp in exponents:
            for i in range(current_length):
                divisors.append(divisors[i] * exp)
    divisors = list(set(divisors))
    divisors.sort()
    return divisors

