        stack.append(x)

    # Compute next greater element (NGE)
    nge = [0] * (n + 2)
    stack = []
    for i in range(n, 0, -1):
        x = p[i - 1]
        while stack and stack[-1] <= x:
            stack.pop()
        if not stack:
            nge[i] = n + 1
        else:
            nge[i] = stack[-1]
        stack.append(x)

    # Find the global maximum
    g = max(p)

    total = 0
    for i in range(1, n + 1):
        if p[i - 1] == g:
            continue
