    c = []
    for _ in range(N):
        row = list(map(int, input[ptr:ptr+N]))
        ptr += N
        c.append(row)

    # Initialize group counts
    group_counts = [[0] * (C + 1) for _ in range(3)]
    for i in range(N):
        for j in range(N):
            g = (i + 1 + j + 1) % 3
            original_color = c[i][j]
            group_counts[g][original_color] += 1

    # Precompute cost for each group and each possible color
    cost = [[0] * (C + 1) for _ in range(3)]
    for g in range(3):
        for y in range(1, C + 1):
            total = 0
            for x in range(1, C + 1):
                count = group_counts[g][x]
                if count == 0:
                    continue
                total += count * D[x - 1][y - 1]
            cost[g][y] = total

    # Find the minimum total cost
    min_total = float('inf')
    for y0 in range(1, C + 1):
        for y1 in range(1, C + 1):
            if y1 == y0:
                continue
            for y2 in range(1, C + 1):
                if y2 == y0 or y2 == y1:
                    continue
                current = cost[0][y0] + cost[1][y1] + cost[2][y2]
                if current < min_total:
                    min_total = current

    print(min_total)

