        if L == 0:
            return 1
        else:
            return 2 + 2 * layers(L-1) + 1

    def patties(L, x):
        if L == 0:
            return 0 if x == 0 else 1
        if x == 0:
            return 0
        if x == 1:
            return 0
        total = 0
        # Bottom bun: no patty
        # Level L-1 burger: recursively count patties in min(x-1, layers(L-1))
        if x > layers(L-1):
            total += patties(L-1, x - 1)
        else:
