        if x >= 2:
            total += 1
        # Second level L-1 burger: same as first
        if x > layers(L-1):
            total += patties(L-1, x - 1)
        else:
            total += patties(L-1, x)
        # Top bun: no patty
        return total

    return patties(N, X)

