def count_patties(N, X):
    if N == 0:
        return 1 if X >= 1 else 0

    # Precompute layers and patties for each level up to N
    layers = [0] * (N + 1)
    patties = [0] * (N + 1)
    layers[0] = 1
    patties[0] = 1
    for l in range(1, N + 1):
        layers[l] = 3 ** l
        patties[l] = 2 * patties[l - 1] + 1

    if X >= layers[N]:
        return patties[N]

    count = 0
    X -= 1  # Part1: bun
    if X == 0:
        return 0

    # Part2: level N-1 burger
    if N - 1 >= 0:
        if X <= layers[N - 1]:
            return count_patties(N - 1, X)
        else:
            count += patties[N - 1]
            X -= layers[N - 1]

    # Part3: patty
    if X >= 1:
        count += 1
        X -= 1

    # Part4: level N-1 burger
    if N - 1 >= 0:
        if X <= layers[N - 1]:
            count += count_patties(N - 1, X)
        else:
            count += patties[N - 1]
            X -= layers[N - 1]

    # Part5: bun
    if X >= 1:
        X -= 1

    return count

