def count_pairs(L_bin):
    n = len(L_bin)
    dp = [[0] * 2 for _ in range(n + 1)]
    dp[0][True] = 1  # Starting state: at position 0, is_tight=True

    for pos in range(n):
        for is_tight in [True, False]:
            if dp[pos][is_tight] == 0:
                continue
            current_bit = L_bin[pos]
            for a_bit, b_bit in [(0, 0), (0, 1), (1, 0)]:
                sum_bit = a_bit | b_bit
                if is_tight:
                    if sum_bit > current_bit:
                        continue  # Invalid choice
                    new_is_tight = (sum_bit == current_bit)
                else:
                    new_is_tight = False
                dp[pos + 1][new_is_tight] = (dp[pos + 1][new_is_tight] + dp[pos][is_tight]) % MOD

    total = (dp[n][True] + dp[n][False]) % MOD
    return total

