                            dp[i+1][0] = (dp[i+1][0] + dp[i][state]) % MOD
                    # Assign to b
                    new_sum = dp[i][state] + (1 << i)
                    if new_sum <= int(L, 2):
                        if new_sum == int(L, 2):
                            dp[i+1][1] = (dp[i+1][1] + dp[i][state]) % MOD
                        else:
                            dp[i+1][0] = (dp[i+1][0] + dp[i][state]) % MOD
                    # Assign to neither
