def main():
    N = int(input().strip())
    from collections import defaultdict
    dp = defaultdict(int)
    # Initial state: empty string
    dp[('',)] = 1
    for _ in range(N):
        new_dp = defaultdict(int)
        for state in dp:
            prev, curr = state
            for c in ['A', 'C', 'G', 'T']:
                # Check condition 1: new substring is not AGC
                if len(prev + curr + c) >= 3 and (prev + curr + c) == 'AGC':
                    continue
                # Check condition 2: swapping curr and c does not create AGC
                # After swapping, the last two are c and curr
                # So, check if the substring starting at position i-1 is AGC
                # i-1 is the position of prev, so the substring is prev, c, curr
                if len(prev + c + curr) >= 3 and (prev + c + curr) == 'AGC':
                    continue
                # Also, check if the new pair (curr, c) when swapped (c, curr) does not create AGC in the string
                # The substring starting at i is c, curr, and the next character (if any)
                # But since we're adding c, the next character is beyond, so the only possible AGC is if prev, c, curr is AGC
                # Which is already checked above
                # So, the only condition is that the new substring is not AGC, and the swapped pair does not create AGC
                # So, the two checks above cover both conditions
                # Now, update the state
                new_state = (curr, c)
                new_dp[new_state] = (new_dp[new_state] + dp[state]) % MOD
        dp = new_dp
    # Sum all possible states
    total = sum(dp.values()) % MOD
    print(total)

