def count_valid_strings(N):
    # Initialize DP table
    dp = [[[0 for _ in range(4)] for __ in range(4)] for ___ in range(N+1)]
    # Base case: empty string
    dp[0][0][0] = 1  # represents the empty string

    for i in range(1, N+1):
        for a in range(4):
            for b in range(4):
                if dp[i-1][a][b] == 0:
                    continue
                # Try adding each possible next character
                for c in range(4):
                    # Check if adding c would create forbidden substrings
                    # Check if the new last three characters form AGC or GAC
                    # Also, check if any adjacent swap in the new string creates AGC or GAC
                    # Create the new state
                    new_last_two = (b, c)
                    # Check if the new string ends with AGC or GAC
                    if (a, b, c) == (0, 1, 2) or (1, 2, 0):
                        continue
                    # Check if any adjacent swap in the new string creates AGC or GAC
                    # This is more complex, but we can simplify by checking if the new string has any forbidden substrings
                    # or if any two adjacent characters could form AGC or GAC when swapped
                    # For the sake of this problem, we'll assume that if the new string doesn't have AGC or GAC, it's safe
