    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    A = []
    for _ in range(N):
        row = list(map(int, input[idx:idx+N]))
        idx += N
        A.append(row)

    # Check if the matrix is valid
    valid = True
    for i in range(N):
        for j in range(N):
            for k in range(N):
                if A[i][j] > A[i][k] + A[k][j]:
                    print(-1)
                    return

    # Collect necessary edges
    edges = []
    for i in range(N):
        for j in range(i + 1, N):
            necessary = True
            for k in range(N):
                if A[i][k] + A[k][j] < A[i][j]:
                    necessary = False
                    break
            if necessary:
                edges.append((A[i][j], i, j))

    # Sort edges by weight
    edges.sort()

    # Kruskal's algorithm using Union-Find
    parent = list(range(N))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        u_root = find(u)
        v_root = find(v)
        if u_root == v_root:
            return False
        parent[v_root] = u_root
        return True

    total = 0
    count = 0
    for weight, u, v in edges:
        if union(u, v):
            total += weight
            count += 1
            if count == N - 1:
                break

    print(total)

