def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    K = int(input[1])
    A = list(map(int, input[2:2+N]))

    A.sort()

    # Compute prefix products and prefix_neg
    prefix_products = [1] * (K + 1)
    prefix_neg = [0] * (K + 1)
    for i in range(1, K + 1):
        if i-1 >= len(A):
            break
        prefix_products[i] = (prefix_products[i-1] * A[i-1]) % MOD
        if A[i-1] < 0:
            prefix_neg[i] = prefix_neg[i-1] + 1
        else:
            prefix_neg[i] = prefix_neg[i-1]

    # Compute suffix products and suffix_neg
    suffix_products = [1] * (K + 1)
    suffix_neg = [0] * (K + 1)
    for j in range(1, K + 1):
        if j-1 >= len(A):
            break
        suffix_products[j] = (suffix_products[j-1] * A[-j]) % MOD
        if A[-j] < 0:
            suffix_neg[j] = suffix_neg[j-1] + 1
        else:
            suffix_neg[j] = suffix_neg[j-1]

    max_product = -float('inf')

    for i in range(0, K + 1, 2):
        j = K - i
        if j < 0 or j > K:
            continue
        if i > len(prefix_products) - 1 or j > len(suffix_products) - 1:
            continue
        product = (prefix_products[i] * suffix_products[j]) % MOD
        count_neg = prefix_neg[i] + suffix_neg[j]
        if count_neg % 2 == 0:
            sign = 1
        else:
            sign = -1
        total = sign * product
        if total > max_product:
            max_product = total

    print(max_product % MOD)

