import bisect

def count_pairs(X, A, N):
    count = 0
    for i in range(N):
        a = A[i]
        if a == 0:
            if X >= 0:
                count += (N - i - 1)
            continue
        if a > 0:
            target = X / a
            j_start = i + 1
            j_end = N
            if j_start >= j_end:
                continue
            pos = bisect.bisect_right(A, target, j_start, j_end)
            count_i = pos - j_start
            count += count_i
        else:
            target = X / a
            j_start = i + 1
            j_end = N
            if j_start >= j_end:
                continue
            pos = bisect.bisect_left(A, target, j_start, j_end)
            count_i = j_end - pos
            count += count_i
    return count

def find_kth_product(K, A, N):
    A.sort()
    low = -10**18
    high = 10**18
    while low < high:
        mid = (low + high) // 2
        cnt = count_pairs(mid, A, N)
        if cnt >= K:
            high = mid
        else:
            low = mid + 1
    return low

