    for _ in range(m):
        a, b, c = map(int, sys.stdin.readline().split())
        roads[(a, b)] = c
        roads[(b, a)] = c

    # Create a mapping from town to index
    town_to_idx = {town: idx for idx, town in enumerate(towns)}

    # Precompute distance matrix
    distance = [[0] * r for _ in range(r)]
    for i in range(r):
        for j in range(r):
            if i == j:
                continue
            a, b, c = towns[i]
            a_j, b_j, c_j = towns[j]
            distance[i][j] = roads[(a, b_j)]
            distance[j][i] = distance[i][j]

    # Initialize DP
    INF = float('inf')
    dp = [[INF] * r for _ in range(1 << r)]
    dp[1 << 0][0] = 0  # Starting at town 0 (r_1), mask has only town 0 visited.

    # Iterate over all masks
    for mask in range(1 << r):
        for u in range(r):
            if not (mask & (1 << u)):
                continue
            current_cost = dp[mask][u]
            if current_cost == INF:
                continue
            for v in range(r):
                if v == u:
                    continue
                if (mask & (1 << v)):
                    continue
                new_mask = mask | (1 << v)
                new_cost = current_cost + distance[u][v]
                if new_cost < dp[new_mask][v]:
                    dp[new_mask][v] = new_cost

    full_mask = (1 << r) - 1
    end_town = towns[-1]
    end_idx = town_to_idx[end_town]
    print(dp[full_mask][end_idx])

