        heapq.heappush(kindergartens[b]['heap'], (-a, i+1))
        if a in kindergartens[b]['counter']:
            kindergartens[b]['counter'][a] += 1
        else:
            kindergartens[b]['counter'][a] = 1
        if kindergartens[b]['current_max'] is None or a > kindergartens[b]['current_max']:
            kindergartens[b]['current_max'] = a

    global_heap = []
    for k_id in kindergartens:
        cm = kindergartens[k_id]['current_max']
        if cm is not None:
            heapq.heappush(global_heap, (cm, k_id))

    for _ in range(Q):
