from bisect import bisect_left, insort
from collections import defaultdict

class Kindergarten:
    def __init__(self):
        self.infants = set()
        self.freq = defaultdict(int)
        self.keys = []
        self.current_max = None
        self.is_non_empty = False
        self.is_non_empty_before_adding = False

def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1
    Q = int(input[ptr])
    ptr += 1

    infants = dict()
    kindergartens = dict()

    for i in range(1, N + 1):
        A_i = int(input[ptr])
        ptr += 1
        B_i = int(input[ptr])
        ptr += 1
        infants[i] = B_i
        if B_i not in kindergartens:
            kindergartens[B_i] = Kindergarten()
        kg = kindergartens[B_i]
        kg.infants.add(i)
        kg.freq[A_i] += 1
        insort(kg.keys, A_i)
        if A_i > kg.current_max:
            kg.current_max = A_i
        kg.is_non_empty = True

    current_max_list = []
    for kg in kindergartens.values():
        if kg.is_non_empty:
            current_max_list.append(kg.current_max)
    insort(current_max_list)

    for _ in range(Q):
        C_j = int(input[ptr])
        ptr += 1
        D_j = int(input[ptr])
        ptr += 1

        # Process K_old
        k_old = infants[C_j]
        a = A[C_j]
        kg_old = kindergartens[k_old]
        kg_old.infants.remove(C_j)
        kg_old.freq[a] -= 1
        if kg_old.freq[a] == 0:
            del kg_old.freq[a]
            pos = bisect_left(kg_old.keys, a)
            if pos < len(kg_old.keys) and kg_old.keys[pos] == a:
                kg_old.keys.pop(pos)
        if kg_old.freq:
            if a == kg_old.current_max:
                if len(kg_old.freq) == 1:
                    pass
                else:
                    if kg_old.keys:
                        kg_old.current_max = kg_old.keys[-1]
                    else:
                        kg_old.current_max = None
            else:
                pass
        else:
            kg_old.current_max = None
        if kg_old.is_non_empty:
            kg_old.is_non_empty = (len(kg_old.infants) > 0)
            if not kg_old.is_non_empty:
                if kg_old.current_max is not None:
                    pos = bisect_left(current_max_list, kg_old.current_max)
                    if pos < len(current_max_list) and current_max_list[pos] == kg_old.current_max:
                        current_max_list.pop(pos)
        infants[C_j] = D_j

        # Process D_j
        kg_new = kindergartens[D_j]
        kg_new.infants.add(C_j)
        kg_new.freq[a] += 1
        insort(kg_new.keys, a)
        if a > kg_new.current_max:
            kg_new.current_max = a
        kg_new.is_non_empty = True
        if not kg_new.is_non_empty_before_adding:
            if kg_new.current_max is not None:
                pos = bisect_left(current_max_list, kg_new.current_max)
                if pos < len(current_max_list) and current_max_list[pos] == kg_new.current_max:
                    current_max_list.pop(pos)
                insort(current_max_list, kg_new.current_max)
            kg_new.is_non_empty_before_adding = True

        # Output the evenness
        if current_max_list:
            print(current_max_list[0])
        else:
            print(0)

