    for _ in range(Q):
        c = int(data[ptr])
        ptr += 1
        d = int(data[ptr])
        ptr += 1
        transfers.append((c, d))

    infants = defaultdict(set)
    current_max = dict()
    kindergarten_heaps = defaultdict(list)
    active_k = set()

    for i in range(1, N+1):
        a = A[i-1]
        b = B[i-1]
        infants[b].add(i)
        if b not in current_max or a > current_max[b]:
            current_max[b] = a
            heapq.heappush(kindergarten_heaps[b], -a)
        active_k.add(b)

    current_kindergarten = {i: B[i-1] for i in range(1, N+1)}

    heap_global = []
    for k in active_k:
        if k in current_max:
            heapq.heappush(heap_global, (current_max[k], k))

    output = []

    for c, d in transfers:
        infant = c
        old_k = current_kindergarten[infant]
        new_k = d

        infants[old_k].remove(infant)
        if len(infants[old_k]) == 0:
            active_k.remove(old_k)
        else:
            if current_max[old_k] == A[infant-1]:
                while True:
                    if not heap_global:
                        break
                    current_max_candidate, k = heapq.heappop(heap_global)
                    if k == old_k:
                        if current_max_candidate == current_max[old_k]:
                            if old_k in kindergarten_heaps:
                                if kindergarten_heaps[old_k]:
                                    new_max = -kindergarten_heaps[old_k][0]
                                    current_max[old_k] = new_max
                                    heapq.heappush(heap_global, (current_max[old_k], old_k))
                                else:
                                    pass
                            break
                    if not (k == old_k and current_max_candidate == current_max[old_k]):
                        continue
                if old_k in kindergarten_heaps:
                    if kindergarten_heaps[old_k]:
                        new_max = -kindergarten_heaps[old_k][0]
                        current_max[old_k] = new_max
                        heapq.heappush(heap_global, (current_max[old_k], old_k))

        infants[new_k].add(infant)
        if new_k not in current_max:
            current_max[new_k] = A[infant-1]
            heapq.heappush(kindergarten_heaps[new_k], -current_max[new_k])
            heapq.heappush(heap_global, (current_max[new_k], new_k))
            active_k.add(new_k)
        else:
            if A[infant-1] > current_max[new_k]:
                current_max[new_k] = A[infant-1]
                heapq.heappush(kindergarten_heaps[new_k], -current_max[new_k])
                heapq.heappush(heap_global, (current_max[new_k], new_k))
        current_kindergarten[infant] = new_k

        while True:
            if not heap_global:
                break
            current_min, k = heapq.heappop(heap_global)
            if k in active_k and current_max[k] == current_min:
