def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1

    S = list(map(int, input[ptr:ptr+N]))
    ptr += N
    T = list(map(int, input[ptr:ptr+N]))
    ptr += N
    U = list(map(int, input[ptr:ptr+N]))
    ptr += N
    V = list(map(int, input[ptr:ptr+N]))
    ptr += N

    # Check if N is 0, but according to constraints, N >=1
    if N == 0:
        print(-1)
        return

    # For each bit, check row and column constraints
    possible = True
    for k in range(64):
        row_req = [ [0, 0] for _ in range(N) ]  # [bit, must_set]
        col_req = [ [0, 0] for _ in range(N) ]

        for i in range(N):
            s = S[i]
            u = U[i]
            if s == 0:
                # AND case: all a[i][j] must have bits set in u, and at least one missing for others
                row_req[i][0] = u
                row_req[i][1] = 1  # must have all bits set in u
            else:
                # OR case: at least one a[i][j] has each bit in u set, others can't have extra bits
                row_req[i][0] = u
                row_req[i][1] = 0  # no must_set, just that OR is u

        for j in range(N):
            t = T[j]
            v = V[j]
            if t == 0:
                # AND case: all a[i][j] must have bits set in v
                col_req[j][0] = v
                col_req[j][1] = 1  # must have all bits set in v
            else:
                # OR case: at least one a[i][j] has each bit in v set
                col_req[j][0] = v
                col_req[j][1] = 0  # no must_set, just that OR is v

        # Now check for each cell
        for i in range(N):
            for j in range(N):
                # Check row and column constraints for this bit
                row_bit = row_req[i][0]
                row_must = row_req[i][1]
                col_bit = col_req[j][0]
                col_must = col_req[j][1]

                # Determine what the row requires for this bit
                if row_must:
                    # Row requires all a[i][j] to have this bit set
                    row_set = (row_bit >> k) & 1
                else:
                    # Row requires that at least one a[i][j] has this bit not set
                    row_set = 0

                # Determine what the column requires for this bit
                if col_must:
                    # Column requires all a[i][j] to have this bit set
                    col_set = (col_bit >> k) & 1
                else:
                    # Column requires that at least one a[i][j] has this bit not set
                    col_set = 0

                # Now, check if row and column constraints for this bit are compatible
                if row_set != col_set:
                    possible = False
                    break
            if not possible:
                break
        if not possible:
            break

    if not possible:
        print(-1)
        return

    # Now construct the matrix
    matrix = []
    for i in range(N):
        row = []
        for j in range(N):
            # Determine the bit constraints for this cell
            row_bit = row_req[i][0]
            col_bit = col_req[j][0]

            # For each bit, check if it must be set or not
            val = 0
            for k in range(64):
                row_must = row_req[i][1]
                col_must = col_req[j][1]

                if row_must:
                    # Row requires this bit set
                    bit_set = (row_bit >> k) & 1
                else:
                    # Row allows this bit to be unset (but if column requires it, it must be set)
                    bit_set = 0

                if col_must:
                    # Column requires this bit set
                    bit_col_set = (col_bit >> k) & 1
                else:
                    # Column allows this bit to be unset (but if row requires it, it must be set)
                    bit_col_set = 0

                # Determine if this bit must be set
                if bit_set != bit_col_set:
                    # This should have been checked earlier, but just in case
                    possible = False
                    break
                if bit_set:
                    val |= (1 << k)
            if not possible:
                break
            row.append(val)
        if not possible:
            break
        matrix.append(row)

    if possible:
        # Print the matrix
        for row in matrix:
            print(''.join(map(str, row)))
    else:
        print(-1)

