def main():
    import sys
    from collections import deque

    H, W, N, *rest = list(map(int, sys.stdin.read().split()))
    a = rest[:N]
    a = [x for x in a]

    grid = [[0 for _ in range(W)] for _ in range(H)]
    current_color = 0

    # Directions: right, left, up, down
    dirs = [ (0,1), (1,0), (0,-1), (-1,0) ]

    for i in range(N):
        ai = a[i]
        if ai == 0:
            continue
        # Assign color i+1 to a connected region
        # Start from the top-left corner
        start = (0, 0)
        if grid[start[0]][start[1]] != 0:
            continue
        # Assign color i+1 to this region
        color = i + 1
        queue = deque()
        queue.append(start)
        grid[start[0]][start[1]] = color
        count = 1
        while queue:
            x, y = queue.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W:
                    if grid[nx][ny] == 0:
                        grid[nx][ny] = color
                        queue.append( (nx, ny) )
                        count += 1
                        if count == ai:
                            break
            if count == ai:
                break
        if count != ai:
            # This should not happen as per problem statement
            print("Invalid solution")
            return

    # Now, check if all a_i are satisfied
    color_counts = [0] * (N+1)
    for i in range(H):
        for j in range(W):
            color = grid[i][j]
            color_counts[color] += 1
    for i in range(N):
        if color_counts[i+1] != a[i]:
            print("Invalid solution")
            return

    # Now, check 4-connectedness for each color
    for i in range(1, N+1):
        visited = set()
        queue = deque()
        for x in range(H):
            for y in range(W):
                if grid[x][y] == i and (x, y) not in visited:
                    visited.add( (x, y) )
                    queue.append( (x, y) )
        if len(visited) == 0:
            continue
        # Check if all visited are connected
        while queue:
            x, y = queue.popleft()
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
                if 0 <= nx < H and 0 <= ny < W:
                    if grid[nx][ny] == i and (nx, ny) not in visited:
                        visited.add( (nx, ny) )
                        queue.append( (nx, ny) )
        if len(visited) != color_counts[i]:
            print("Invalid solution")
            return

    # Output the grid
    for row in grid:
        print(''.join(map(str, row)))

